@tool
extends SceneTree

func _init():
	# Create the root node
	var root = Node2D.new()
	root.name = "Player"

	# Create AnimationPlayer
	var anim_player = AnimationPlayer.new()
	anim_player.name = "AnimationPlayer"
	root.add_child(anim_player)
	anim_player.owner = root

	# Add animations to AnimationPlayer
	var anim_names = ["idle", "walk_north", "walk_south", "walk_east", "walk_west", "attack"]
	var anim_library = AnimationLibrary.new()
	for name in anim_names:
		var anim = Animation.new()
		anim.length = 1.0
		var track_idx = anim.add_track(Animation.TYPE_VALUE)
		anim.track_set_path(track_idx, ".:position")
		anim.track_insert_key(track_idx, 0.0, Vector2.ZERO)
		anim_library.add_animation(name, anim)
	anim_player.add_animation_library("", anim_library)

	# Create AnimationTree
	var anim_tree = AnimationTree.new()
	anim_tree.name = "AnimationTree"
	root.add_child(anim_tree)
	anim_tree.owner = root

	# Point anim_player to AnimationPlayer
	anim_tree.anim_player = NodePath("../AnimationPlayer")

	# Create AnimationNodeStateMachine for the tree_root
	var state_machine = AnimationNodeStateMachine.new()

	# Create Locomotion: AnimationNodeBlendSpace2D
	var locomotion = AnimationNodeBlendSpace2D.new()

	var anim_idle = AnimationNodeAnimation.new()
	anim_idle.animation = &"idle"
	locomotion.add_blend_point(anim_idle, Vector2(0, 0))

	var anim_north = AnimationNodeAnimation.new()
	anim_north.animation = &"walk_north"
	locomotion.add_blend_point(anim_north, Vector2(0, -1))

	var anim_south = AnimationNodeAnimation.new()
	anim_south.animation = &"walk_south"
	locomotion.add_blend_point(anim_south, Vector2(0, 1))

	var anim_east = AnimationNodeAnimation.new()
	anim_east.animation = &"walk_east"
	locomotion.add_blend_point(anim_east, Vector2(1, 0))

	var anim_west = AnimationNodeAnimation.new()
	anim_west.animation = &"walk_west"
	locomotion.add_blend_point(anim_west, Vector2(-1, 0))

	# Add Locomotion to state machine
	state_machine.add_node("Locomotion", locomotion)

	# Create Attack: AnimationNodeAnimation whose animation is set to &"attack"
	var attack_node = AnimationNodeAnimation.new()
	attack_node.animation = &"attack"
	state_machine.add_node("Attack", attack_node)

	# Configure transitions
	# Start -> Locomotion
	var trans_start = AnimationNodeStateMachineTransition.new()
	trans_start.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_AUTO
	state_machine.add_transition("Start", "Locomotion", trans_start)

	# Locomotion -> Attack: condition_attack
	var trans_to_attack = AnimationNodeStateMachineTransition.new()
	trans_to_attack.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_AUTO
	trans_to_attack.advance_condition = &"condition_attack"
	state_machine.add_transition("Locomotion", "Attack", trans_to_attack)

	# Attack -> Locomotion: switch mode AtEnd
	var trans_to_loco = AnimationNodeStateMachineTransition.new()
	trans_to_loco.advance_mode = AnimationNodeStateMachineTransition.ADVANCE_MODE_AUTO
	trans_to_loco.switch_mode = AnimationNodeStateMachineTransition.SWITCH_MODE_AT_END
	state_machine.add_transition("Attack", "Locomotion", trans_to_loco)

	# Set tree_root
	anim_tree.tree_root = state_machine

	# Create PlayerAnimController node
	var controller = Node.new()
	controller.name = "PlayerAnimController"
	var script = load("res://scripts/PlayerAnimController.gd")
	controller.set_script(script)
	root.add_child(controller)
	controller.owner = root

	# Save scene
	var packed_scene = PackedScene.new()
	var err = packed_scene.pack(root)
	if err == OK:
		err = ResourceSaver.save(packed_scene, "res://scenes/Player.tscn")
		if err == OK:
			print("Successfully saved Player.tscn")
		else:
			print("Error saving Player.tscn: ", err)
	else:
		print("Error packing Player: ", err)

	quit()

