func _initialize():
	print("--- Running Headless Locomotion/Attack Test ---")

	# Load the Player scene
	var player_scene = load("res://scenes/Player.tscn")
	if not player_scene:
		print("FAILED: Player.tscn could not be loaded!")
		quit(1)
		return

	var player = player_scene.instantiate()
	if not player:
		print("FAILED: Player scene could not be instantiated!")
		quit(1)
		return

	root.add_child(player)

	var anim_tree: AnimationTree = player.get_node("AnimationTree")
	var anim_player: AnimationPlayer = player.get_node("AnimationPlayer")
	var controller = player.get_node("PlayerAnimController")

	# Activate the AnimationTree
	anim_tree.active = true

	print("Active: ", anim_tree.active)
	var playback = anim_tree.get("parameters/playback")
	print("Playback: ", playback)
	if playback:
		print("Current node before advance: ", playback.get_current_node())

	# Advance the anim_tree manually
	anim_tree.advance(0.1)

	playback = anim_tree.get("parameters/playback")
	if playback:
		print("Current node after advance(0.1): ", playback.get_current_node())

	quit(0)

